Point2f ConcentricSampleDisk(const Point2f &u) {
    // map uniform random numbers to [-1,1]^2
    Float offsetX = 2 * u.x - 1;
    Float offsetY = 2 * u.y - 1;

    if (offsetX == 0 && offsetY == 0) return Point2f(0,0);

    Float r, theta;
    if (std::abs(offsetX) > std::abs(offsetY)) {
        r = offsetX;
        theta = Pi/4 * (offsetY / offsetX);
    } else {
        r = offsetY;
        theta = Pi/2 - Pi/4 * (offsetX / offsetY);
    }
    return Point2f(r * std::cos(theta), r * std::sin(theta));
}

